module dessert_finder (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [15:0] P,\n    \n    output reg [15:0] count,\n    output reg [15:0] beverage,\n    output reg [15:0] main_dish,\n    output reg pair_valid,\n    output reg done\n);\n\n// State encoding\nlocalparam [1:0] IDLE = 2'b00;\nlocalparam [1:0] INIT = 2'b01;\nlocalparam [1:0] CHECK = 2'b10;\nlocalparam [1:0] DONE_STATE = 2'b11;\n\n// Internal registers\nreg [1:0] state, next_state;\nreg [15:0] b_reg, b_next;\nreg [15:0] count_reg, count_next;\nreg [15:0] beverage_reg, beverage_next;\nreg [15:0] main_dish_reg, main_dish_next;\nreg pair_valid_reg, pair_valid_next;\nreg done_reg, done_next;\n\n// Mask computation wires\nwire [9:0] mask_b;\nwire [9:0] mask_m;\nwire [9:0] mask_P;\nwire digits_disjoint;\n\n// Function to compute digit mask (0-9)\nfunction [9:0] compute_mask;\n    input [15:0] number;\n    integer i;\n    reg [3:0] digit;\n    begin\n        compute_mask = 10'd0;\n        for (i = 0; i < 5; i = i + 1) begin\n            if (i == 0) digit = number % 10;\n            else if (i == 1) digit = (number / 10) % 10;\n            else if (i == 2) digit = (number / 100) % 10;\n            else if (i == 3) digit = (number / 1000) % 10;\n            else if (i == 4) digit = (number / 10000) % 10;\n            \n            if (digit != 0 || (number >> (4*i) > 0)) begin\n                compute_mask[digit] = 1'b1;\n            end\n        end\n    end\nendfunction\n\n// Compute current masks\nassign mask_b = compute_mask(b_reg);\nassign mask_m = compute_mask(P - b_reg);\nassign mask_P = compute_mask(P);\n\n// Disjoint digits condition\nassign digits_disjoint = ((mask_b & mask_m) == 10'b0) && \n                         ((mask_b & mask_P) == 10'b0) && \n                         ((mask_m & mask_P) == 10'b0);\n\n// State machine combinational logic\nalways @(*) begin\n    next_state = state;\n    b_next = b_reg;\n    count_next = count_reg;\n    beverage_next = beverage_reg;\n    main_dish_next = main_dish_reg;\n    pair_valid_next = 1'b0;\n    done_next = done_reg;\n\n    case (state)\n        IDLE: begin\n            done_next = 1'b0;\n            if (start) begin\n                next_state = INIT;\n            end\n        end\n        \n        INIT: begin\n            b_next = 16'd1;\n            count_next = 16'd0;\n            next_state = CHECK;\n        end\n        \n        CHECK: begin\n            if (b_reg <= P - b_reg) begin\n                if (digits_disjoint && (b_reg != 16'd0) && ((P - b_reg) != 16'd0)) begin\n                    count_next = count_reg + 16'd1;\n                    beverage_next = b_reg;\n                    main_dish_next = P - b_reg;\n                    pair_valid_next = 1'b1;\n                end\n                \n                if (b_reg < (P - 16'd1)) begin\n                    b_next = b_reg + 16'd1;\n                end else begin\n                    next_state = DONE_STATE;\n                end\n            end else begin\n                next_state = DONE_STATE;\n            end\n        end\n        \n        DONE_STATE: begin\n            done_next = 1'b1;\n            if (!start) begin\n                next_state = IDLE;\n            end\n        end\n        \n        default: next_state = IDLE;\n    endcase\nend\n\n// Sequential logic\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        b_reg <= 16'd0;\n        count_reg <= 16'd0;\n        beverage_reg <= 16'd0;\n        main_dish_reg <= 16'd0;\n        pair_valid_reg <= 1'b0;\n        done_reg <= 1'b0;\n    end else begin\n        state <= next_state;\n        b_reg <= b_next;\n        count_reg <= count_next;\n        beverage_reg <= beverage_next;\n        main_dish_reg <= main_dish_next;\n        pair_valid_reg <= pair_valid_next;\n        done_reg <= done_next;\n    end\nend\n\n// Output assignments\nalways @(*) begin\n    count = count_reg;\n    beverage = beverage_reg;\n    main_dish = main_dish_reg;\n    pair_valid = pair_valid_reg;\n    done = done_reg;\nend\n\nendmodule